package com.bank.index.model;

import jakarta.persistence.*;
import java.math.BigDecimal;
import java.time.LocalDateTime;

@Entity
@Table(name = "transactions",
       indexes = @Index(name = "ix_txn_acct_date", columnList = "account_id, created_at"))
public class Transaction {
    @Id
    @Column(name = "txn_id")
    private String txnId;

    @Column(name = "account_id", nullable = false)
    private String accountId;

    @Column(nullable = false)
    private BigDecimal amount;

    @Column(nullable = false)
    private String direction;

    @Column(name = "created_at", nullable = false)
    private LocalDateTime createdAt;

    protected Transaction() { }

    public Transaction(String txnId, String accountId, BigDecimal amount,
                       String direction, LocalDateTime createdAt) {
        this.txnId = txnId;
        this.accountId = accountId;
        this.amount = amount;
        this.direction = direction;
        this.createdAt = createdAt;
    }
    public String getTxnId() { return txnId; }
    public String getAccountId() { return accountId; }
    public BigDecimal getAmount() { return amount; }
    public String getDirection() { return direction; }
    public LocalDateTime getCreatedAt() { return createdAt; }
}
