package com.bank.index.repository;

import com.bank.index.model.Transaction;
import org.springframework.data.domain.Pageable;
import org.springframework.data.jpa.repository.JpaRepository;
import java.util.List;

public interface TransactionRepository extends JpaRepository<Transaction, String> {
    // This derived query maps to WHERE account_id = ? ORDER BY created_at DESC,
    // which is served by the composite index ix_txn_acct_date.
    List<Transaction> findByAccountIdOrderByCreatedAtDesc(String accountId, Pageable page);
}
