package com.bank.index.service;

import com.bank.index.model.Transaction;
import com.bank.index.repository.TransactionRepository;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.data.domain.PageRequest;
import org.springframework.stereotype.Service;
import java.util.List;

@Service
public class TransactionService {
    private static final Logger log = LoggerFactory.getLogger(TransactionService.class);
    private final TransactionRepository txnRepo;

    public TransactionService(TransactionRepository txnRepo) {
        this.txnRepo = txnRepo;
    }

    public List<Transaction> recentTransactions(String accountId, int limit) {
        log.info("Fetching last {} transactions for account {}", limit, accountId);
        // The composite index turns a full scan of 200M rows into a fast index seek.
        List<Transaction> result =
            txnRepo.findByAccountIdOrderByCreatedAtDesc(accountId, PageRequest.of(0, limit));
        log.info("Returned {} transactions using index ix_txn_acct_date", result.size());
        return result;
    }
}
